import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Verification scenarios","description":"","frontmatter":{},"headers":[],"relativePath":"feature/workspace-chat-collaboration/test.md","filePath":"feature/workspace-chat-collaboration/test.md"}'),n={name:"feature/workspace-chat-collaboration/test.md"};function s(o,e,d,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="verification-scenarios" tabindex="-1">Verification scenarios <a class="header-anchor" href="#verification-scenarios" aria-label="Permalink to &quot;Verification scenarios&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>Scenario</th><th>Expected result</th><th>Status</th></tr></thead><tbody><tr><td>C01</td><td>Load chat with authenticated fixture workspace</td><td>History and channel directory come from authenticated API responses</td><td>Passed with isolated fixtures, including production bundle</td></tr><tr><td>C02</td><td>Open package/campaign context links, reject missing context ID and switch context during a pending send</td><td>Sends retain exact context; optimistic/failed rows stay in that context; filtered view does not mark messages read</td><td>Passed after fixing optimistic context filtering; persisted Mongo filtering not exercised in browser</td></tr><tr><td>C03</td><td>Search saved channel history, including no matches; clear search and filter pins</td><td>Requests scoped to selected channel; empty feedback; clear restores history</td><td>Passed with fixture API; live search not exercised</td></tr><tr><td>C04</td><td>Retry history errors and load older messages</td><td>Stable deduplication/order; loaded history survives pagination errors</td><td>Passed; real connection loss/reconnect remains unexecuted</td></tr><tr><td>C05</td><td>Failed send, retry, then canonical acknowledgement</td><td>Same client ID reused; one visible message remains</td><td>Passed with simulated HTTP 503 and REST/STOMP acknowledgement</td></tr><tr><td>C06</td><td>Switch conversation while history response is delayed</td><td>No late response appears in the new conversation</td><td>Passed for channel switching; account/workspace A→B→A scenarios remain unexecuted</td></tr><tr><td>C07</td><td>View filtered history or hide browser tab</td><td>Unseen messages are not marked read merely on receipt; visible bottom view advances read state</td><td>Passed: context filter, simulated document visibility and visible read request</td></tr><tr><td>C08</td><td>Copy message; simulate clipboard denial</td><td>Success only on completed copy; useful error otherwise</td><td>Passed using in-page clipboard mock; OS clipboard untouched</td></tr><tr><td>C09</td><td>Open/close details and mobile navigation with keyboard; transfer navigation to create-channel sheet</td><td>Focus returns to visible opener; transfer retains focus in new sheet</td><td>Passed after fixing controlled-sheet focus restoration; repeated on production bundle</td></tr><tr><td>C10</td><td>Vietnamese/English</td><td>Parallel keys; no raw keys or broken layout</td><td>Passed: 102 matching leaf keys; VI/EN browser checks</td></tr><tr><td>C11</td><td>Light/dark at 375, 768 and 1440px</td><td>No horizontal overflow; composer above bottom navigation</td><td>Passed in both themes at all three widths; screenshots inspected</td></tr><tr><td>C12</td><td>Typecheck, changed-file lint and production build</td><td>Pass or clearly attributable existing failures</td><td>Passed after both final fixes; unrelated media-library dynamic-import warning remains</td></tr></tbody></table><p>Browser fixture results establish frontend behavior only. Real Mongo/STOMP multi-user behavior requires the running backend and authorized test accounts.</p><h2 id="executed-collaboration-workflows" tabindex="-1">Executed collaboration workflows <a class="header-anchor" href="#executed-collaboration-workflows" aria-label="Permalink to &quot;Executed collaboration workflows&quot;">​</a></h2><ul><li>Create a PRIVATE channel with invited member; automatically select the returned channel and send a message.</li><li>Add/remove a member, save managers-only setting, archive the channel, observe read-only composer, then restore it.</li><li>Create a DIRECT conversation and send; simulate failed send and retry with the same client ID, leaving one canonical row.</li><li>Open a thread and send a reply; root reply count increments and reply stays out of the top-level timeline.</li><li>Add reaction, pin a message, filter pins, search with no match and clear search.</li><li>Insert an authorized member as plain-text <code>@name</code>; focus returns to composer. Shift+Enter inserts a newline.</li></ul><p>These checks verify frontend requests, state and rendering against an isolated fixture. They do not prove backend concurrency, channel creation idempotency or actual user-to-user delivery.</p><h2 id="confirmed-backend-scope-cases" tabindex="-1">Confirmed backend scope cases <a class="header-anchor" href="#confirmed-backend-scope-cases" aria-label="Permalink to &quot;Confirmed backend scope cases&quot;">​</a></h2><ul><li>B01: Outsider/removed workspace member cannot list/read/send/subscribe; private channel and DIRECT additionally require membership, including for managers.</li><li>B02: CLIENT discovers general and invited channels only; internal PUBLIC access does not grant private access.</li><li>B03: Same request creates one channel/DM; repeated send creates one message; conflicting client ID reuse is rejected.</li><li>B04: Legacy history/read/unread never includes new non-general messages. Existing general history survives.</li><li>B05: Cross-workspace or cross-channel root/message is rejected for thread, reaction, pin and read APIs.</li><li>B06: Archived channel rejects sends/reactions/pins/member writes; allowed manager can restore. General/DM invariant changes are rejected.</li><li>B07: Atomic reaction add/remove and member updates do not overwrite unrelated fields; failed persistence emits no content event.</li><li>B08: Channel search escapes regex metacharacters, pages stably and scopes every query to authorized channel/root.</li><li>B09: Both inbound subscription and outbound delivery reject revoked channel membership; legacy topic receives general only.</li><li>B10: Browser fixture exercises create channel, settings, invite/remove, DM, thread, reaction, pin, server search and reconnect without fake production state.</li></ul><h2 id="backend-verification-results-—-2026-10-22" tabindex="-1">Backend verification results — 2026-10-22 <a class="header-anchor" href="#backend-verification-results-—-2026-10-22" aria-label="Permalink to &quot;Backend verification results — 2026-10-22&quot;">​</a></h2><p>Executed <code>mvn -o -q &quot;-Dtest=ChatChannelAccessTest,ChatChannelMessagesTest,ChatChannelQueriesTest,ChatChannelInterceptorTest,ChatServiceImplTest,WorkspaceAccessServiceTest&quot; test</code>: <strong>30 tests passed, 0 failures/errors/skipped</strong>.</p><table tabindex="0"><thead><tr><th>Suite</th><th style="text-align:right;">Tests</th><th>Evidence</th></tr></thead><tbody><tr><td>ChatChannelAccessTest</td><td style="text-align:right;">6</td><td>Private/DM membership even for managers, client public-channel invitation, archived/restricted posting, general/DM management invariants, no owner fallback</td></tr><tr><td>ChatChannelMessagesTest</td><td style="text-align:right;">7</td><td>Client-ID reuse, cross-channel conflict, foreign root, revoked access, reaction allowlist, failed-save event suppression and private channel-only publication</td></tr><tr><td>ChatChannelQueriesTest</td><td style="text-align:right;">4</td><td>Legacy/general query isolation, channel-scoped escaped search and invalid cursor rejection</td></tr><tr><td>ChatChannelInterceptorTest</td><td style="text-align:right;">5</td><td>Bearer authentication, destination validation, active workspace subscription, revoked outbound delivery and existing task role checks</td></tr><tr><td>ChatServiceImplTest</td><td style="text-align:right;">6</td><td>Existing general message validation, normalization, duplicate reuse, history limit and cross-workspace package rejection</td></tr><tr><td>WorkspaceAccessServiceTest</td><td style="text-align:right;">2</td><td>Active client membership resolution and outsider denial</td></tr></tbody></table><p>These unit regressions cover portions of B01–B09. Full live coverage remains pending for DM/channel creation races, concurrent member/reaction updates, legacy read/unread against Mongo, channel-specific revocation on an actual broker, and failure/reconnect across multiple authenticated clients. B10&#39;s UI workflows passed except actual connection loss/reconnect.</p><p><code>mvn -o -q -DskipTests package</code> also passed. Produced <code>brandhub-business-service/target/brandhub-business-service-0.0.1-SNAPSHOT.jar</code>.</p><h2 id="final-frontend-build-results-—-2026-10-22" tabindex="-1">Final frontend/build results — 2026-10-22 <a class="header-anchor" href="#final-frontend-build-results-—-2026-10-22" aria-label="Permalink to &quot;Final frontend/build results — 2026-10-22&quot;">​</a></h2><ul><li><code>npm run type-check</code>: passed.</li><li><code>npm exec -- eslint src/pages/chat src/types/chatCollaboration.ts src/services/chatCollaborationService.ts src/components/layout/Layout.tsx</code>: passed.</li><li><code>npm run build</code>: passed, 4,374 modules transformed; output in <code>brandhub-web/dist</code>.</li><li>Existing warning: <code>mockContentLibraryService.ts</code> is imported both statically and dynamically in media library, so its dynamic import does not split a separate chunk. No build error.</li><li>Opened the built app using <code>vite preview</code> at <code>http://127.0.0.1:4173</code>, with isolated HTTP/STOMP fixtures. History, thread and sheet focus regressions passed; no JavaScript runtime errors in this production smoke run.</li><li>Six English theme/viewport checks measured document width equal to viewport width; composer remained within the viewport. At 375px, textarea bottom was 683px and bottom navigation began at 748px in an 812px viewport.</li><li>Expected HTTP 503 console entries came only from deliberate send/history failure simulations. No unexpected JavaScript exception or dialog accessibility warning was observed.</li></ul><p>Local verification artifacts are in workspace <code>output/playwright/</code>, outside application source and commits:</p><ul><li><code>chat-production-thread-desktop-vi.png</code>: production desktop with thread.</li><li><code>chat-production-mobile-light-vi.png</code>, <code>chat-production-mobile-dark-vi.png</code>: production mobile themes.</li><li><code>chat-final-{light,dark}-{375,768,1440}-en.png</code>: English responsive/theme matrix.</li><li><code>final-web-build.log</code>: final production build output.</li></ul><p>Mongo migration/index scripts were syntax-checked only. They were not applied to shared databases. No deployment or live multi-user end-to-end test was performed.</p>',18)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
